  return await pool.query<T>(text, values);
}

export async function runErasureWorker(signal: AbortSignal): Promise<void> {
  const service = new ErasureService();
  const workerId = `privacy-worker-${randomUUID()}`;
  let lastRecovery = 0;
  while (!signal.aborted) {
